'use client';

import React, { useState, useEffect } from 'react';
import { useRouter, useParams } from 'next/navigation';
import "../../../../../public/styles/bootstrap.css";
import "../../../../../public/styles/game_create.css";
import { getToken, clearTokens, getMembershipId } from '../../../../../token';

const API_BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL || "https://api.hpground.xyz/api/wargame-problems";

type WargameProblem = {
  title: string;
  detail: string;
  source: string | null;
  kind: string;
  level: string;
  flag: string;
  dockerfileLink: string;
};

export default function WargameEdit() {
  const router = useRouter();
  const params = useParams();
  const problemId = params?.problemId;

  const [problem, setProblem] = useState<WargameProblem>({
    title: "",
    detail: "",
    source: null,
    kind: "",
    level: "⭐⭐",
    flag: "",
    dockerfileLink: "",
  });

  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    const storedMembershipId = getMembershipId();
    if (!storedMembershipId) {
      alert('로그인이 필요합니다.');
      clearTokens();
      router.push('/login');
      return;
    }

    const loadData = async () => {
      const token = await getToken();
      if (!token) {
        alert('로그인이 만료되었습니다. 다시 로그인 해주세요.');
        clearTokens();
        router.push('/login');
        return;
      }

      if (!problemId) {
        setLoading(false);
        return;
      }

      try {
        console.log("Fetching problem data with ID:", problemId);
        const res = await fetch(`${API_BASE_URL}/${problemId}`, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        if (!res.ok) throw new Error('문제 정보를 불러오는데 실패했습니다.');

        const data = await res.json();
        console.log("API Response Data:", data);

        const problemData = data.result;
        console.log("Parsed Problem Data:", problemData);

        const levelMapReverse: Record<string, string> = {
          "1": "⭐",
          "2": "⭐⭐",
          "3": "⭐⭐⭐",
        };

        setProblem({
          title: problemData.title ?? "",
          detail: problemData.detail ?? "",
          source: problemData.source ?? null,
          kind: problemData.kind ?? "",
          level: levelMapReverse[problemData.level] ?? "⭐⭐",
          flag: problemData.flag ?? "",
          dockerfileLink: problemData.dockerfileLink ?? "",
        });
      } catch (err) {
        if (err instanceof Error) {
          console.error("Fetch error:", err);
          alert(err.message);
        } else {
          console.error("Unknown error:", err);
          alert("알 수 없는 오류가 발생했습니다.");
        }
        router.push("/game");
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, [problemId, router]);

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>
  ) => {
    const { name, value } = e.target;
    console.log(`Input Change - Field: ${name}, Value: ${value}`);
    setProblem((prev) => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      console.log("Selected File:", e.target.files[0]);
      setFile(e.target.files[0]);
    }
  };

  const handleSubmit = async () => {
    console.log("handleSubmit: Starting submission...");
    if (!problemId) {
      alert("문제 ID가 없습니다.");
      return;
    }

    try {
      const accessToken = await getToken();
      console.log("handleSubmit: Retrieved Access Token:", accessToken);

      if (!accessToken) {
        alert("로그인이 만료되었습니다. 다시 로그인 해주세요.");
        clearTokens();
        router.push("/login");
        return;
      }

      const levelMap: Record<string, number> = {
        "⭐": 1,
        "⭐⭐": 2,
        "⭐⭐⭐": 3,
      };

      const problemData = {
        title: problem.title,
        type: "WARGAME",
        problemType: "WARGAME",
        detail: problem.detail,
        source: problem.source,
        tags: [],
        kind: problem.kind ? problem.kind.toUpperCase() : "",
        level: levelMap[problem.level] ?? 1,
        flag: problem.flag,
        dockerfileLink: problem.dockerfileLink,
      };

      console.log("handleSubmit: Problem Data to Submit:", problemData);

      const headers = {
        Authorization: `Bearer ${accessToken}`,
      };

      const formData = new FormData();
      formData.append("data", new Blob([JSON.stringify(problemData)], { type: "application/json" }));

      if (file) {
        console.log("handleSubmit: Adding File to FormData:", file);
        formData.append("file", file);
      }

      console.log("handleSubmit: FormData ready, sending PUT request...");
      const response = await fetch(`${API_BASE_URL}/${problemId}`, {
        method: "PUT",
        headers,
        body: formData,
      });

      console.log("handleSubmit: Response Status:", response.status);

      if (response.ok) {
        alert("문제가 성공적으로 수정되었습니다.");
        router.push("/game");
      } else {
        const errorText = await response.text();
        console.error("handleSubmit: Submission failed:", errorText);
        alert("문제 수정 실패: " + errorText);
      }
    } catch (err) {
      if (err instanceof Error) {
        console.error("handleSubmit: Error during submission:", err);
        alert(err.message);
      } else {
        console.error("handleSubmit: Unknown error:", err);
        alert("문제 수정 중 알 수 없는 오류가 발생했습니다.");
      }
    }
  };

  if (loading) return <div>로딩중...</div>;

  return (
    <div className="container">
      <h3 className="pageTitle">문제 수정</h3>
      <div className="form-group">
        <label>제목</label>
        <input
          name="title"
          value={problem.title ?? ""}
          onChange={handleChange}
          className="problemSelector"
        />
      </div>
      <div className="form-group">
        <label>문제 설명</label>
        <textarea
          name="detail"
          value={problem.detail ?? ""}
          onChange={handleChange}
          className="textarea problemSelector"
        />
      </div>
      <div className="form-group">
        <label>미리보기</label>
        <div className="preview">
          {problem.detail?.split('\n').map((line, index) => (
            <React.Fragment key={index}>
              {line}
              <br />
            </React.Fragment>
          ))}
        </div>
      </div>
      <div className="form-group">
        <label>문제 종류</label>
        <select
          name="kind"
          value={problem.kind ?? ""}
          onChange={handleChange}
          className="problemSelector"
        >
          <option value="">문제 종류를 선택하세요</option>
          <option value="WEBHACKING">웹해킹</option>
          <option value="SYSTEM">포너블</option>
          <option value="REVERSING">리버싱</option>
          <option value="CRYPTO">암호학</option>
        </select>
      </div>
      <div className="form-group">
        <label>난이도</label>
        <select
          name="level"
          value={problem.level ?? "⭐⭐"}
          onChange={handleChange}
          className="problemSelector"
        >
          <option value="⭐">⭐ (쉬움)</option>
          <option value="⭐⭐">⭐⭐ (보통)</option>
          <option value="⭐⭐⭐">⭐⭐⭐ (어려움)</option>
        </select>
      </div>
      <div className="form-group">
        <label>정답 플래그</label>
        <input
          name="flag"
          value={problem.flag ?? ""}
          onChange={handleChange}
          className="problemSelector"
        />
      </div>
      <div className="form-group">
        <label>Dockerfile 링크</label>
        <input
          name="dockerfileLink"
          value={problem.dockerfileLink ?? ""}
          onChange={handleChange}
          className="problemSelector"
        />
      </div>
      <div className="form-group">
        <label>파일 업로드</label>
        <input type="file" onChange={handleFileChange} className="problemSelector" />
      </div>
      <div className="writeButtonWrap">
        <button className="btnDark" onClick={handleSubmit}>
          문제 수정
        </button>
      </div>
    </div>
  );
}
